INSERT INTO `broadcasters` VALUES
(1,'Andahayani','andahayani','Classier','/static/img/broadcasters/andahayani.jpg','It\'s Not About How Life is Treating You but You Are Treating Life. Suka public speaking, broadcasting, dan menjelajahi tempat baru.','Jambi','17 Oktober','anda_joseph','anda_joseph','Andahayani Yoseph',1,1,'2026-07-19 01:37:09','2026-07-20 21:53:27'),
(3,'Dhanny Yudiska','dhanny-yudiska','Classier','/static/img/broadcasters/dhanny-yudiska.png','Im a grown man... I do whatever i want! Suka musik, film, broadcasting, dan hal-hal yang membawa kebahagiaan.','Maninjau','18 Agustus','dhannyyudiska','dhannyyudiska','dhanny\'arif\'yudiska',3,1,'2026-07-19 01:37:09','2026-07-20 21:53:27'),
(4,'Edo Prussiano','edo-prussiano','Classier','/static/img/broadcasters/edo-prussiano.jpg','Kalo mau kaya, ya harus capek! Suka healing.','Padang','28 Juni','edo_pruss17','edo_pruss17',NULL,8,1,'2026-07-19 01:37:09','2026-07-21 13:43:24'),
(5,'Jasmine Andrea','jasmine-andrea','Classier','/static/img/broadcasters/jasmine-andrea.jpg','Live is Art. Suka membaca, menulis, musik, film, dan seni.','Batusangkar','06 September','Jasmine Andrea','jasmineandrea06',NULL,5,1,'2026-07-19 01:37:09','2026-07-20 21:53:27'),
(6,'Puti Adelya','puti-adelya','Classier',NULL,'It\'s just a bad day, not a bad life. Suka buku, film, seni, dan proyek sosial.','Padang','31 Mei','karzmp',NULL,NULL,6,1,'2026-07-19 01:37:09','2026-07-19 01:37:09'),
(7,'Via Helvita','via-helvita','Classier','/static/img/broadcasters/via-helvita.png','Hidup Gak Neko Neko. Suka traveling.','Jakarta','30 Oktober','vivi_chressya','vivi_chressya','Vivi d\' Chressya',7,0,'2026-07-19 01:37:09','2026-07-21 13:44:11'),
(8,'Yeni Maiasnita','yeni-maiasnita','Classier','/static/img/broadcasters/yeni-maiasnita.png','Always Do The Best And Enjoy Your Life. Suka film, broadcasting, human interest, dan psikologi. Membawakan \"Communitalk with Yeni Maiasnita\".','Sawahlunto','28 Mei','aunty.cantik','auntycantiq','aunty cantik',2,1,'2026-07-19 01:37:09','2026-07-21 13:42:40');
